// Package rt is the runtime support library for Go code generated by gosm
// from WebAssembly modules.
package rt

import (
	"fmt"
	"runtime"
	"strings"
)

// MaxCallDepth bounds the wasm call depth. A call beyond it traps with
// "call stack exhausted" instead of overflowing the Go stack.
var MaxCallDepth = 60000

// Trap is a WebAssembly trap. Generated code panics with *Trap.
type Trap struct {
	Msg string
}

func (t *Trap) Error() string { return "wasm trap: " + t.Msg }

func NewTrap(msg string) *Trap { return &Trap{Msg: msg} }

// Common traps.
var (
	ErrUnreachable   = &Trap{"unreachable"}
	ErrIntOverflow   = &Trap{"integer overflow"}
	ErrDivByZero     = &Trap{"integer divide by zero"}
	ErrInvalidConv   = &Trap{"invalid conversion to integer"}
	ErrMemOOB        = &Trap{"out of bounds memory access"}
	ErrTableOOB      = &Trap{"out of bounds table access"}
	ErrArrayOOB      = &Trap{"out of bounds array access"}
	ErrNullRef       = &Trap{"null reference"}
	ErrNullFunc      = &Trap{"null function reference"}
	ErrNullStruct    = &Trap{"null structure reference"}
	ErrNullArray     = &Trap{"null array reference"}
	ErrNullI31       = &Trap{"null i31 reference"}
	ErrNullExn       = &Trap{"null exception reference"}
	ErrUninitElem    = &Trap{"uninitialized element"}
	ErrIndirectType  = &Trap{"indirect call type mismatch"}
	ErrCast          = &Trap{"cast failure"}
	ErrExhausted     = &Trap{"call stack exhausted"}
	ErrDataOOB       = &Trap{"out of bounds memory access"}
	ErrArrayTooLarge = &Trap{"allocation too large"}
	ErrNotString     = &Trap{"not a string"}
)

// Exception is a WebAssembly exception (thrown by throw / throw_ref and
// carried by exnref values).
type Exception struct {
	Tag    *Tag
	Values []any
}

func (e *Exception) Error() string {
	return fmt.Sprintf("uncaught wasm exception (%d values)", len(e.Values))
}

// Tag is an exception tag. Tags are compared by identity.
type Tag struct {
	Type *RTT // function type of the tag's parameters
}

// Throw panics with a new exception.
func Throw(t *Tag, values ...any) {
	panic(&Exception{Tag: t, Values: values})
}

// ThrowRef rethrows an exnref.
func ThrowRef(e *Exception) {
	if e == nil {
		panic(ErrNullExn)
	}
	panic(e)
}

// Catch runs f and converts a wasm trap, uncaught wasm exception, or Go
// runtime error raised by generated code into an error. Other panics
// propagate.
func Catch(f func()) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = AsError(r)
			if err == nil {
				panic(r)
			}
		}
	}()
	f()
	return nil
}

// AsError converts a recovered panic value into a wasm error, or nil if the
// value did not originate from wasm semantics.
func AsError(r any) error {
	switch v := r.(type) {
	case *Trap:
		return v
	case *Exception:
		return v
	case *LinkError:
		return v
	case *Delegated:
		return v.Exn
	case runtime.Error:
		msg := v.Error()
		switch {
		case strings.Contains(msg, "nil pointer"):
			return &Trap{"null reference"}
		case strings.Contains(msg, "index out of range"), strings.Contains(msg, "slice bounds"):
			return &Trap{"out of bounds array access"}
		case strings.Contains(msg, "divide by zero"):
			return ErrDivByZero
		case strings.Contains(msg, "interface conversion"):
			return &Trap{"indirect call type mismatch: " + msg}
		case strings.Contains(msg, "stack"):
			return ErrExhausted
		}
		return &Trap{msg}
	}
	return nil
}

// B2I converts a bool to a wasm i32.
func B2I(b bool) int32 {
	if b {
		return 1
	}
	return 0
}

// Sel implements select.
func Sel[T any](c int32, a, b T) T {
	if c != 0 {
		return a
	}
	return b
}

// NonNull implements ref.as_non_null.
func NonNull[T comparable](x T) T {
	var z T
	if x == z {
		panic(ErrNullRef)
	}
	return x
}

// Exhausted panics with the call-stack-exhausted trap.
func Exhausted() { panic(ErrExhausted) }

// Delegated carries an exception delegated (legacy "delegate") to the try
// block with id Target in the same function (0 = the function's caller).
type Delegated struct {
	Exn    *Exception
	Target int
}

// Unwrap returns the exception a handler with the given try id should
// process, or re-panics r if it is not for this handler.
func Unwrap(r any, id int) *Exception {
	switch v := r.(type) {
	case *Exception:
		return v
	case *Delegated:
		if v.Target == id {
			return v.Exn
		}
	}
	panic(r)
}

// UndelegateFrame is deferred by functions that delegate to their caller.
func UndelegateFrame() {
	if r := recover(); r != nil {
		if d, ok := r.(*Delegated); ok && d.Target == 0 {
			panic(d.Exn)
		}
		panic(r)
	}
}
